def suggested_link_title(page):
    label = LINK_TITLES.get(page.url_path) or SERVICE_LINK_TITLES.get(page.url_path, '')
    return label if label != page.title else ''

class Command(BaseCommand):
    help = 'Review every Page and fill short menu/breadcrumb titles where useful.'

    def add_arguments(self, parser):
        parser.add_argument('--apply', action='store_true', help='Apply changes (default: preview only).')
        parser.add_argument('--overwrite', action='store_true', help='Replace manually edited link titles.')

    def handle(self, *args, **options):
        reviewed = changed = 0
        for page in Page.objects.order_by('tree_id', 'lft').iterator():
            reviewed += 1
            label = suggested_link_title(page)
            if not label or (page.link_title and not options['overwrite']) or label == page.link_title:
                continue
            self.stdout.write(f'{page.url_path or "/"}: {page.title} -> {label}')
            if options['apply']:
                Page.objects.filter(pk=page.pk).update(link_title=label)
            changed += 1
        self.stdout.write(f'Reviewed {reviewed}; {"updated" if options["apply"] else "would update"} {changed}')
